let catalog;export async function pickEmoji(t,onPick){catalog||=await fetch(new URL('./assets/emoji.json',import.meta.url)).then(r=>r.json());const d=document.createElement('dialog');d.className='emoji-picker';d.innerHTML='<h2></h2><input id="emojiSearch" type="search"><select id="emojiCategory"></select><div class="emoji-grid"></div><button class="text-button" data-more></button><button class="small-primary" data-close></button>';d.querySelector('h2').textContent=t('allEmoji');const search=d.querySelector('input'),select=d.querySelector('select');search.placeholder=t('searchEmoji');search.setAttribute('aria-label',t('searchEmoji'));select.setAttribute('aria-label',t('emojiCategory'));for(const name of ['All',...new Set(catalog.map(e=>e.group))]){const o=document.createElement('option');o.value=name;o.textContent=name==='All'?t('all'):name;select.append(o);}let limit=250;const grid=d.querySelector('.emoji-grid');function draw(){const list=catalog.filter(e=>(select.value==='All'||e.group===select.value)&&(e.name+' '+e.emoji).toLowerCase().includes(search.value.toLowerCase()));grid.replaceChildren(...list.slice(0,limit).map(e=>{const b=document.createElement('button');b.type='button';b.textContent=e.emoji;b.title=e.name;b.setAttribute('aria-label',e.name);b.onclick=()=>{onPick(e.emoji);d.close();d.remove();};return b;}));d.querySelector('[data-more]').hidden=limit>=list.length;}d.querySelector('[data-more]').textContent=t('moreEmoji');d.querySelector('[data-more]').onclick=()=>{limit+=250;draw();};d.querySelector('[data-close]').textContent=t('close');d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();};d.oncancel=()=>d.remove();search.oninput=select.onchange=()=>{limit=250;draw();};document.body.append(d);d.showModal();draw();search.focus();}
